<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Rule Audit','description'=>'Check a password against common character and length rules locally.','url'=>'https://smarttoolz.in/tools/password-rule-audit/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Password Rule Audit</h1><p>Check common password rules in your browser.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="p" type="password" placeholder="Enter password"><button id="go" class="tool-btn">Audit Password</button><pre id="o"></pre></div></section></main><script>go.onclick=()=>{let s=p.value;o.textContent=[`Length 12+: ${s.length>=12?'PASS':'FAIL'}`,`Uppercase: ${/[A-Z]/.test(s)?'PASS':'FAIL'}`,`Lowercase: ${/[a-z]/.test(s)?'PASS':'FAIL'}`,`Number: ${/\d/.test(s)?'PASS':'FAIL'}`,`Symbol: ${/[^A-Za-z0-9]/.test(s)?'PASS':'FAIL'}`].join('\n')}</script><?php smarttoolz_tool_page_end(); ?>